            {
                return false;
            }

            if (!TryReadByte(reader, out var operationKindByte, out error))
            {
                return false;
            }

            var operationKind = (RealtimeWorldInteractionOperationKind)operationKindByte;

            if (!TryReadBoolean(reader, out var succeeded, out error))
            {
                return false;
            }

            if (!TryReadInt64(reader, out var targetRevision, out error))
            {
                return false;
            }

            if (!TryReadInt64(reader, out var itemStateRevision, out error))
            {
                return false;
            }

            if (!TryReadString(reader, MaximumWorldInteractionMessageLength, out var message, out error, allowBlank: true))
            {
                return false;
            }

            RealtimeError errorValue = null;
            if (!succeeded)
            {
                if (!TryReadError(reader, out errorValue, out error))
                {
                    return false;
                }
            }

            value = new RealtimeWorldInteractionResult(operationId, interactionSessionId, operationKind, succeeded, targetRevision, itemStateRevision, message, errorValue);
            return true;
        }

        private static bool IsValidWorldInteractionResult(RealtimeWorldInteractionResult value)
        {
            if (value == null
                || value.OperationId == Guid.Empty
                || !IsDefined(value.OperationKind)
                || value.TargetRevision < 0
                || value.ItemStateRevision < 0
                || value.Message == null
                || value.Message.Length > MaximumWorldInteractionMessageLength
                || !value.Succeeded != (value.Error != null)
                || (value.Error != null && !IsValidError(value.Error)))
            {
                return false;
            }

            return SatisfiesRules(value);
        }

