            WriteString(writer, value.Id, MaximumWorldActorCapabilityIdLength, "value.Id");
            writer.Write((byte)value.Kind);
            WriteString(writer, value.DisplayName, MaximumWorldActorCapabilityNameLength, "value.DisplayName");
            writer.Write(value.IsAvailable);
            writer.Write(value.Revision);
        }

        private static bool TryReadWorldActorCapability(BinaryReader reader, out RealtimeWorldActorCapability value, out string error)
        {
            value = null;
            if (!TryReadString(reader, MaximumWorldActorCapabilityIdLength, out var id, out error))
            {
                return false;
            }

            if (!TryReadByte(reader, out var kindByte, out error))
            {
                return false;
            }

            var kind = (RealtimeWorldActorCapabilityKind)kindByte;

            if (!TryReadString(reader, MaximumWorldActorCapabilityNameLength, out var displayName, out error))
            {
                return false;
            }

            if (!TryReadBoolean(reader, out var isAvailable, out error))
            {
                return false;
            }

            if (!TryReadInt64(reader, out var revision, out error))
            {
                return false;
            }

            var decoded = new RealtimeWorldActorCapability(id, kind, displayName, isAvailable, revision);
            if (!IsValidWorldActorCapability(decoded))
            {
                error = "World actor capability is invalid.";
                return false;
            }

            value = decoded;
            return true;
        }

        private static bool IsValidWorldActorCapability(RealtimeWorldActorCapability value)
        {
            if (value == null
                || string.IsNullOrWhiteSpace(value.Id)
                || value.Id.Length > MaximumWorldActorCapabilityIdLength
                || !IsDefined(value.Kind)
                || string.IsNullOrWhiteSpace(value.DisplayName)
                || value.DisplayName.Length > MaximumWorldActorCapabilityNameLength
                || value.Revision < 1)
            {
                return false;
            }

            return true;
        }

        private static bool IsDefined(RealtimeWorldActorCapabilityKind value)
        {
            return (byte)value >= 1 && (byte)value <= 9;
        }

        private static bool IsDefined(RealtimeWorldActorKind value)
        {
            return (byte)value >= 1 && (byte)value <= 2;
        }

        private static bool IsDefined(RealtimeWorldActorDisposition value)
        {
            return (byte)value >= 1 && (byte)value <= 3;
        }

        private static bool IsDefined(RealtimeWorldActorActivityTier value)
        {
            return (byte)value >= 1 && (byte)value <= 3;
        }

        private static bool IsDefined(RealtimeWorldInteractionOperationKind value)
        {
            return (byte)value >= 1 && (byte)value <= 3;
        }

        private static bool IsDefined(RealtimeWorldInteractionTargetKind value)
        {
            return (byte)value >= 1 && (byte)value <= 2;
        }

        private static bool IsDefined(RealtimeNpcLifecycleActionKind value)
        {
            return (byte)value >= 0 && (byte)value <= 4;
        }
    }
}
